error_handling.code:
command_that_might_fail || {
  echo "Command failed with status $?" >&2
  exit 1
}

set -e # Exit immediately if a command exits with a non-zero status.

comments.code:
# Single line comment in Bash
# Shell scripts begin with a shebang:
#!/usr/bin/env bash

pattern_matching.code:
case "$val" in
    1) echo "One" ;;
    2|3) echo "Two or Three" ;;
    *) echo "Other" ;;
esac

oop_classes.code:
# Functions serve as reusable components
person_greet() {
    local name="$1"
    echo "Hello $name"
}
